Index: src/WordPicker.Web/Pages/WordLists/Index.cshtml
===================================================================
--- src/WordPicker.Web/Pages/WordLists/Index.cshtml	
+++ src/WordPicker.Web/Pages/WordLists/Index.cshtml	
@@ -1,56 +1,60 @@
 @page
 @model WordPicker.Web.Pages.WordLists.IndexModel
 @{
     ViewData["Title"] = "Word Lists";
 }

 <div class="d-flex justify-content-between align-items-center mb-3">
     <h1>Word Lists</h1>
+    @if (Model.WordLists.Any())
+    {
+        <a asp-page="./Pick" class="btn btn-primary">Pick Words</a>
+    }
 </div>

 @if (!Model.WordLists.Any())
 {
     <div class="alert alert-info">
         <p>No word lists yet. Create your first one below!</p>
     </div>
 }
 else
 {
     <div class="list-group mb-4">
         @foreach (var list in Model.WordLists)
         {
             <div class="list-group-item d-flex justify-content-between align-items-center">
                 <div>
                     <a asp-page="./Details" asp-route-id="@list.Id" class="text-decoration-none">
                         <strong>@list.Name</strong>
                     </a>
                     <br />
                     <small class="text-muted">Created: @list.CreatedAt.ToString("g")</small>
                 </div>
                 <a asp-page="./Delete" asp-route-id="@list.Id" class="btn btn-sm btn-outline-danger">Delete</a>
             </div>
         }
     </div>
 }

 <hr class="my-4" />

 <h2>Create New Word List</h2>

 <div class="row">
     <div class="col-md-6">
         <form method="post">
             <div asp-validation-summary="ModelOnly" class="text-danger"></div>
             <div class="mb-3">
                 <label asp-for="NewWordList.Name" class="form-label">Name</label>
                 <input asp-for="NewWordList.Name" class="form-control" placeholder="Enter list name" />
                 <span asp-validation-for="NewWordList.Name" class="text-danger"></span>
             </div>
             <button type="submit" class="btn btn-primary">Create List</button>
         </form>
     </div>
 </div>

 @section Scripts {
     <partial name="_ValidationScriptsPartial" />
 }

Index: src/WordPicker.Web/Pages/WordLists/Pick.cshtml.cs
===================================================================
--- src/WordPicker.Web/Pages/WordLists/Pick.cshtml.cs	
+++ src/WordPicker.Web/Pages/WordLists/Pick.cshtml.cs	
@@ -0,0 +1,72 @@
+using Microsoft.AspNetCore.Mvc;
+using Microsoft.AspNetCore.Mvc.RazorPages;
+using Microsoft.EntityFrameworkCore;
+using WordPicker.Web.Data;
+using WordPicker.Web.Models;
+
+namespace WordPicker.Web.Pages.WordLists;
+
+public class PickModel : PageModel
+{
+    private readonly ApplicationDbContext _context;
+
+    public PickModel(ApplicationDbContext context)
+    {
+        _context = context;
+    }
+
+    public IList<WordList> WordLists { get; set; } = new List<WordList>();
+
+    public List<PickResult> Results { get; set; } = new();
+
+    public bool ShowResults => Results.Count > 0;
+
+    [BindProperty]
+    public List<int> SelectedListIds { get; set; } = new();
+
+    public async Task OnGetAsync()
+    {
+        WordLists = await _context.WordLists
+            .OrderByDescending(w => w.CreatedAt)
+            .ToListAsync();
+    }
+
+    public async Task<IActionResult> OnPostAsync()
+    {
+        WordLists = await _context.WordLists
+            .OrderByDescending(w => w.CreatedAt)
+            .ToListAsync();
+
+        if (SelectedListIds.Count == 0)
+        {
+            ModelState.AddModelError(string.Empty, "Select at least one list.");
+            return Page();
+        }
+
+        foreach (var listId in SelectedListIds)
+        {
+            var list = WordLists.FirstOrDefault(w => w.Id == listId);
+            if (list == null)
+                continue;
+
+            var words = await _context.WordEntries
+                .Where(e => e.WordListId == listId)
+                .ToListAsync();
+            var word = words.OrderBy(_ => Random.Shared.Next()).FirstOrDefault();
+
+            Results.Add(new PickResult
+            {
+                ListName = list.Name,
+                Word = word?.Value
+            });
+        }
+
+        return Page();
+    }
+
+    public class PickResult
+    {
+        public string ListName { get; set; } = string.Empty;
+        public string? Word { get; set; }
+    }
+}

Index: tests/WordPicker.Tests/Web/Pages/WordLists/PickTests.cs
===================================================================
--- tests/WordPicker.Tests/Web/Pages/WordLists/PickTests.cs	
+++ tests/WordPicker.Tests/Web/Pages/WordLists/PickTests.cs	
@@ -0,0 +1,133 @@
+using Microsoft.AspNetCore.Mvc;
+using Microsoft.AspNetCore.Mvc.RazorPages;
+using Microsoft.VisualStudio.TestTools.UnitTesting;
+using WordPicker.Web.Models;
+using WordPicker.Web.Pages.WordLists;
+
+namespace WordPicker.Tests.Web.Pages.WordLists;
+
+[TestClass]
+public class PickTests : BaseTest
+{
+    [TestMethod]
+    [TestCategory(TestCategories.Unit)]
+    public async Task OnGetAsync_WhenCalled_PopulatesWordLists()
+    {
+        using var context = CreateContext();
+        var pageModel = new PickModel(context);
+
+        await pageModel.OnGetAsync();
+
+        Assert.IsNotNull(pageModel.WordLists);
+        Assert.AreEqual(0, pageModel.WordLists.Count);
+        Assert.IsFalse(pageModel.ShowResults);
+    }
+
+    [TestMethod]
+    [TestCategory(TestCategories.Unit)]
+    public async Task OnGetAsync_WhenWordListsExist_ReturnsSortedList()
+    {
+        using var context = CreateContext();
+        context.WordLists.Add(new WordList { Name = "First List", CreatedAt = DateTime.UtcNow.AddDays(-1) });
+        context.WordLists.Add(new WordList { Name = "Second List", CreatedAt = DateTime.UtcNow });
+        context.SaveChanges();
+
+        var pageModel = new PickModel(context);
+
+        await pageModel.OnGetAsync();
+
+        Assert.AreEqual(2, pageModel.WordLists.Count);
+        Assert.AreEqual("Second List", pageModel.WordLists[0].Name);
+        Assert.AreEqual("First List", pageModel.WordLists[1].Name);
+    }
+
+    [TestMethod]
+    [TestCategory(TestCategories.Unit)]
+    public async Task OnPostAsync_WhenNoListsSelected_ReturnsPageWithError()
+    {
+        using var context = CreateContext();
+        context.WordLists.Add(new WordList { Name = "Test List" });
+        context.SaveChanges();
+
+        var pageModel = new PickModel(context);
+        pageModel.SelectedListIds = new List<int>();
+
+        var result = await pageModel.OnPostAsync();
+
+        Assert.IsInstanceOfType(result, typeof(PageResult));
+        Assert.IsFalse(pageModel.ModelState.IsValid);
+        Assert.AreEqual(0, pageModel.Results.Count);
+        Assert.IsFalse(pageModel.ShowResults);
+    }
+
+    [TestMethod]
+    [TestCategory(TestCategories.Unit)]
+    public async Task OnPostAsync_WhenValidSelection_PicksOneWordPerList()
+    {
+        using var context = CreateContext();
+        var list = new WordList { Name = "Test List" };
+        context.WordLists.Add(list);
+        context.SaveChanges();
+        context.WordEntries.Add(new WordEntry { WordListId = list.Id, Value = "apple" });
+        context.WordEntries.Add(new WordEntry { WordListId = list.Id, Value = "banana" });
+        context.SaveChanges();
+
+        var pageModel = new PickModel(context);
+        pageModel.SelectedListIds = new List<int> { list.Id };
+
+        var result = await pageModel.OnPostAsync();
+
+        Assert.IsInstanceOfType(result, typeof(PageResult));
+        Assert.IsTrue(pageModel.ShowResults);
+        Assert.AreEqual(1, pageModel.Results.Count);
+        Assert.AreEqual("Test List", pageModel.Results[0].ListName);
+        Assert.IsNotNull(pageModel.Results[0].Word);
+    }
+
+    [TestMethod]
+    [TestCategory(TestCategories.Unit)]
+    public async Task OnPostAsync_WhenListHasNoWords_ShowsPlaceholder()
+    {
+        using var context = CreateContext();
+        var list = new WordList { Name = "Empty List" };
+        context.WordLists.Add(list);
+        context.SaveChanges();
+
+        var pageModel = new PickModel(context);
+        pageModel.SelectedListIds = new List<int> { list.Id };
+
+        var result = await pageModel.OnPostAsync();
+
+        Assert.IsInstanceOfType(result, typeof(PageResult));
+        Assert.IsTrue(pageModel.ShowResults);
+        Assert.AreEqual(1, pageModel.Results.Count);
+        Assert.AreEqual("Empty List", pageModel.Results[0].ListName);
+        Assert.IsNull(pageModel.Results[0].Word);
+    }
+
+    [TestMethod]
+    [TestCategory(TestCategories.Unit)]
+    public async Task REDACTED()
+    {
+        using var context = CreateContext();
+        var listA = new WordList { Name = "List A" };
+        var listB = new WordList { Name = "List B" };
+        context.WordLists.AddRange(listA, listB);
+        context.SaveChanges();
+        context.WordEntries.Add(new WordEntry { WordListId = listA.Id, Value = "hello" });
+        context.WordEntries.Add(new WordEntry { WordListId = listB.Id, Value = "world" });
+        context.SaveChanges();
+
+        var pageModel = new PickModel(context);
+        pageModel.SelectedListIds = new List<int> { listA.Id, listB.Id };
+
+        var result = await pageModel.OnPostAsync();
+
+        Assert.IsInstanceOfType(result, typeof(PageResult));
+        Assert.AreEqual(2, pageModel.Results.Count);
+        Assert.AreEqual("List A", pageModel.Results[0].ListName);
+        Assert.AreEqual("hello", pageModel.Results[0].Word);
+        Assert.AreEqual("List B", pageModel.Results[1].ListName);
+        Assert.AreEqual("world", pageModel.Results[1].Word);
+    }
+}

